// db.js - an in-memory Postgres, ready to use. You do NOT edit this file.
//
// It behaves like a real PostgreSQL database (same SQL, same `pool.query`,
// same `$1` parameters) but it lives in memory, so there is nothing to install
// or configure: `npm start` just works. Every run rebuilds the same tables
// with the same rows below, so the answers never change between runs.
import { newDb } from 'pg-mem'

const SCHEMA = `
  CREATE TABLE locations (
    id   SERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    city TEXT NOT NULL
  );
  CREATE TABLE sightings (
    id          SERIAL PRIMARY KEY,
    location_id INTEGER NOT NULL REFERENCES locations(id),
    ghost_type  TEXT NOT NULL,
    witnesses   INTEGER NOT NULL,
    reported_at DATE NOT NULL
  );
`

// Fixed seed data. Reason about the expected answers from this table by hand.
//
//   locations                         sightings (id, loc, ghost_type, witnesses, reported_at)
//   1 Manila Film Center, Manila      1  loc1  apparition   5  2026-01-10
//   2 Diplomat Hotel, Baguio          2  loc3  white lady   2  2026-02-14
//   3 Balete Drive, Quezon City       3  loc2  poltergeist  7  2026-03-01
//   4 Clark Air Base, Angeles         4  loc1  orb          1  2026-03-15
//                                     5  loc3  white lady   4  2026-04-02
//                                     6  loc4  shadow       3  2026-04-20
//                                     7  loc2  apparition   6  2026-05-05
//                                     8  loc3  white lady   2  2026-05-30
const SEED = `
  INSERT INTO locations (name, city) VALUES
    ('Manila Film Center', 'Manila'),
    ('Diplomat Hotel', 'Baguio'),
    ('Balete Drive', 'Quezon City'),
    ('Clark Air Base', 'Angeles');

  INSERT INTO sightings (location_id, ghost_type, witnesses, reported_at) VALUES
    (1, 'apparition',  5, '2026-01-10'),
    (3, 'white lady',  2, '2026-02-14'),
    (2, 'poltergeist', 7, '2026-03-01'),
    (1, 'orb',         1, '2026-03-15'),
    (3, 'white lady',  4, '2026-04-02'),
    (4, 'shadow',      3, '2026-04-20'),
    (2, 'apparition',  6, '2026-05-05'),
    (3, 'white lady',  2, '2026-05-30');
`

const db = newDb()
db.public.none(SCHEMA + SEED)
const { Pool } = db.adapters.createPg()
export const pool = new Pool()
